// Throttle: only re-chase a given case once every 24h, tracked in this
// workflow's own static data since desk has no durable "last chased"
// field to read instead (see the sticky note above). Static data is
// n8n-instance-local, not authoritative -- see the sticky note.
const staticData = $getWorkflowStaticData('global');
if (!staticData.lastChasedAt) staticData.lastChasedAt = {};

const caseId = $json.id;
const lastChasedIso = staticData.lastChasedAt[caseId];
const now = new Date();

let shouldChase = true;
let hoursSinceLastChase = null;

if (lastChasedIso) {
  const last = new Date(lastChasedIso);
  hoursSinceLastChase = (now.getTime() - last.getTime()) / (1000 * 60 * 60);
  shouldChase = hoursSinceLastChase >= 24;
}

return [{
  json: {
    ...$json,
    shouldChase,
    hoursSinceLastChase
  }
}];

